 const actions=node('div',undefined,'queue-actions'),container=node('div'),next=button('Next page',async()=>load(next.dataset.cursors?JSON.parse(next.dataset.cursors):null),true);next.hidden=true;actions.append(button('Apply and save view',async()=>{saveView('Receive',{scope:scope.value,tab:saved.tab,search:search.value,live:view('Receive',saved).live});await show('Receive');}),next);c.append(actions,container);
